<?php
require_once __DIR__.'/includes/bootstrap.php'; $pdo=db();
$q=trim((string)($_GET['q']??'')); $cat=trim((string)($_GET['category']??''));
$sql="SELECT e.*,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='registered') AS registered_count FROM events e WHERE e.status='published' AND e.event_date>=NOW()";$p=[];
if($q!==''){$sql.=" AND (e.title LIKE ? OR e.description LIKE ? OR e.venue LIKE ?)";$like='%'.$q.'%';array_push($p,$like,$like,$like);}
if($cat!==''){$sql.=" AND e.category=?";$p[]=$cat;}$sql.=" ORDER BY e.event_date";$st=$pdo->prepare($sql);$st->execute($p);$events=$st->fetchAll();
$cats=$pdo->query("SELECT DISTINCT category FROM events WHERE status='published' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);
$pageTitle='Discover events';require __DIR__.'/includes/header.php';?>
<section class="hero mb-5"><div class="text-uppercase small fw-bold mb-3">YOUR CAMPUS, CONNECTED</div><h1 class="display-4 mb-3">Find your next campus experience.</h1><p class="lead mb-4">Discover workshops, tech talks, cultural fests and student activities. Register in a few clicks and keep your events in one place.</p><?php if(!user()):?><a class="btn btn-light btn-lg me-2" href="register.php">Join the community</a><?php endif;?><a class="btn btn-outline-light btn-lg" href="#events">Explore events ↓</a></section>
<div id="events" class="d-flex flex-column flex-md-row justify-content-between align-items-md-end gap-3 mb-4"><div><div class="text-primary small fw-bold">WHAT'S HAPPENING</div><h2 class="fw-bold">Upcoming events</h2><p class="text-secondary mb-0"><?=count($events)?> event(s) found</p></div><form class="d-flex gap-2 flex-column flex-sm-row" method="get"><input class="form-control" name="q" placeholder="Search events or venue" value="<?=e($q)?>"><select class="form-select" name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option <?= $cat===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="btn btn-primary">Search</button></form></div>
<?php if(!$events):?><div class="empty"><h3 class="h5">No upcoming events yet</h3><p class="text-secondary">An administrator can publish the first event from the admin dashboard.</p><?php if(!user()):?><a class="btn btn-primary" href="register.php">Create account</a><?php endif;?></div><?php else:?><div class="row g-4"><?php foreach($events as $ev):$cap=(int)$ev['capacity'];$n=(int)$ev['registered_count'];?><div class="col-md-6 col-xl-4"><article class="event-card"><div class="event-strip"></div><div class="event-body"><span class="pill"><?=e($ev['category'])?></span><h3 class="h5 fw-bold mt-3"><?=e($ev['title'])?></h3><p class="text-secondary"><?=e(mb_strimwidth($ev['description'],0,125,'…'))?></p><div class="meta">📅 <?=e(date('D, d M Y · h:i A',strtotime($ev['event_date'])))?><br>📍 <?=e($ev['venue'])?></div><div class="d-flex justify-content-between mt-3 small"><span>Seats filled</span><strong><?=$n?> / <?=$cap?></strong></div><div class="progress mt-1" style="height:6px"><div class="progress-bar bg-primary" style="width:<?=$cap?min(100,(int)round($n/$cap*100)):100?>%"></div></div><a class="btn btn-primary btn-sm mt-3" href="event.php?id=<?=(int)$ev['id']?>">View event</a></div></article></div><?php endforeach;?></div><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>